import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int Cin, int H, int W,
    int Cout, int K, int stride, int pad,
    int Hout, int Wout)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * Cout * Hout * Wout;
    if (idx >= total) return;

    int wo = idx % Wout;
    int tmp = idx / Wout;
    int ho = tmp % Hout;
    tmp = tmp / Hout;
    int co = tmp % Cout;
    int n = tmp / Cout;

    float sum = bias[co];

    int h_start = ho * stride - pad;
    int w_start = wo * stride - pad;

    for (int ci = 0; ci < Cin; ++ci) {
        const float* input_ptr = input + ((n * Cin + ci) * H) * W;
        const float* weight_ptr = weight + ((co * Cin + ci) * K) * K;
        for (int kh = 0; kh < K; ++kh) {
            int h = h_start + kh;
            if (h < 0 || h >= H) continue;
            const float* input_row = input_ptr + h * W;
            const float* weight_row = weight_ptr + kh * K;
            for (int kw = 0; kw < K; ++kw) {
                int w = w_start + kw;
                if (w < 0 || w >= W) continue;
                sum += input_row[w] * weight_row[kw];
            }
        }
    }

    output[idx] = sum;
}

torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad)
{
    input = input.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();

    int N = input.size(0);
    int Cin = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int Cout = weight.size(0);
    int K = weight.size(2);

    int Hout = (H + 2 * pad - K) / stride + 1;
    int Wout = (W + 2 * pad - K) / stride + 1;

    auto output = torch::empty({N, Cout, Hout, Wout}, input.options());

    int total = N * Cout * Hout * Wout;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    conv2d_forward_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, Cin, H, W,
        Cout, K, stride, pad,
        Hout, Wout
    );

    return output;
}
"""

conv2d_header = r"""
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_header,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels, self.kernel_size, self.kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        # Initialize similar to nn.Conv2d default init
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()
        bias = self.bias.cuda().contiguous()
        return conv2d_module.conv2d_forward_cuda(
            x, weight, bias, self.stride, self.padding
        )


def get_inputs():
    batch_size = 256
    return [torch.rand(batch_size, 3, 224, 224)]


def get_init_inputs():
    num_classes = 1000
    return [num_classes]

